/* Fleet live recording waveform (design.md capture control: the level meter).
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * nothing here varies between apps. Normalized from grocery-shopping-
 * automation's `startWave()` (app/static/modules/audio.js), generalized from a
 * canvas drawn into one fixed element to DOM bars drawn into any host.
 *
 * Pairs with rec-wave.css. Exports:
 *   attachRecWave(host, stream, opts) -> stop()   the strip + timer in a host
 *   createLevelSource(stream?)        -> source   the shared level reader
 *   SILENCE_RMS, SILENCE_MS                       the shared silence verdict
 *
 * One level source serves both the strip and a caller's own silent-mic
 * notice (`onSilent` / `onSignal`), so a take opens one AudioContext, not two.
 */

'use strict';

// A dead input route reads exact zeros and a quiet room's noise floor sits well
// above this, so only an input with no signal at all stays under it.
export const SILENCE_RMS = 0.002;
// How long the input must stay under the floor before the strip reads "silent".
export const SILENCE_MS = 1500;

const DEFAULT_BARS = 24;
const MIN_BARS = 4;
const MAX_BARS = 64;
const DEFAULT_HEIGHT = 24;
// A silent bar keeps a sliver so the strip still reads as a strip, not as a gap.
const MIN_BAR = 0.08;
// Speech peaks sit well under full scale; this lifts them to fill the strip.
const GAIN = 2.5;
const FFT_SIZE = 512;
// ~16 fps is smooth for bars; the reduced-motion meter changes four times a second.
const TICK_MS = 60;
const REDUCED_TICK_MS = 250;

function audioContextClass() {
  return globalThis.AudioContext || globalThis.webkitAudioContext || null;
}

function clamp(value, low, high) {
  return Math.min(high, Math.max(low, value));
}

/**
 * Open an AudioContext on the mic stream and return a reader of its level, or
 * null when the browser has no Web Audio or refuses to build the graph (the
 * caller then runs on the timer alone; an unmeasured take is never "silent").
 *
 * iOS Safari starts a context suspended and resumes it only inside a user
 * gesture, so call this in the tap handler. When the stream is not there yet
 * (the first getUserMedia prompt), call it with no stream before the await and
 * hand the stream over later with `source.connect(stream)`.
 *
 * @param {MediaStream} [stream]
 * @returns {{running: boolean, connect(stream: MediaStream): void,
 *            read(bars: number): ({rms: number, levels: number[]}|null),
 *            close(): void}|null}
 */
export function createLevelSource(stream) {
  const Ctx = audioContextClass();
  if (!Ctx) {
    console.info('[rec-wave] input level not measured: no Web Audio');
    return null;
  }
  let ctx;
  let analyser;
  try {
    ctx = new Ctx();
    // A suspended context reads zeros, which would look exactly like a silent route.
    if (ctx.resume) ctx.resume().catch(() => {});
    analyser = ctx.createAnalyser();
    analyser.fftSize = FFT_SIZE;
  } catch (exc) {
    console.info('[rec-wave] input level not measured', exc);
    return null;
  }
  const floats = typeof analyser.getFloatTimeDomainData === 'function';
  const samples = floats ? new Float32Array(analyser.fftSize) : new Uint8Array(analyser.fftSize);
  let connected = false;
  let closed = false;

  function connect(mic) {
    if (connected || closed || !mic) return;
    try {
      ctx.createMediaStreamSource(mic).connect(analyser);
      connected = true;
    } catch (exc) {
      console.info('[rec-wave] input level not measured', exc);
    }
  }

  if (stream) connect(stream);

  return {
    // Running and wired to a stream: the only state in which a level means anything.
    get running() {
      return connected && !closed && (!ctx.state || ctx.state === 'running');
    },
    connect,
    read(bars) {
      if (!this.running) return null;
      if (floats) analyser.getFloatTimeDomainData(samples);
      else analyser.getByteTimeDomainData(samples);
      const slice = Math.max(1, Math.floor(samples.length / bars));
      const levels = [];
      let sumSquares = 0;
      for (let i = 0; i < samples.length; i += 1) {
        const v = floats ? samples[i] : (samples[i] - 128) / 128;
        sumSquares += v * v;
      }
      for (let b = 0; b < bars; b += 1) {
        let peak = 0;
        for (let j = b * slice; j < (b + 1) * slice && j < samples.length; j += 1) {
          const v = floats ? samples[j] : (samples[j] - 128) / 128;
          peak = Math.max(peak, Math.abs(v));
        }
        levels.push(clamp(peak * GAIN, 0, 1));
      }
      return { rms: Math.sqrt(sumSquares / samples.length), levels };
    },
    close() {
      if (closed) return;
      closed = true;
      try { ctx.close().catch(() => {}); } catch (_) { /* best effort */ }
    },
  };
}

function prefersReducedMotion() {
  try {
    return !!(globalThis.matchMedia && globalThis.matchMedia('(prefers-reduced-motion: reduce)').matches);
  } catch (_) {
    return false;
  }
}

function formatElapsed(ms) {
  const total = Math.floor(ms / 1000);
  const seconds = String(total % 60).padStart(2, '0');
  return `${Math.floor(total / 60)}:${seconds}`;
}

function span(className) {
  const el = document.createElement('span');
  el.className = className;
  return el;
}

/** The wave's DOM: the bars (or the one meter under reduced motion) and the timer. */
function buildWave(bars, reduced, height, withTimer) {
  const root = span('rec-wave');
  root.setAttribute('aria-hidden', 'true');
  root.dataset.motion = reduced ? 'reduced' : 'full';
  root.style.setProperty('--rec-wave-height', `${height}px`);
  const strip = span(reduced ? 'rec-wave-meter' : 'rec-wave-bars');
  const fills = Array.from({ length: reduced ? 1 : bars }, () => document.createElement('i'));
  strip.append(...fills);
  root.appendChild(strip);
  let timeEl = null;
  if (withTimer) {
    timeEl = span('rec-wave-time');
    root.appendChild(timeEl);
  }
  return { root, fills, timeEl };
}

/** Draw one reading: bar heights, or the meter's width. An empty reading is the flat strip. */
function paintLevels(fills, reduced, levels) {
  if (reduced) {
    fills[0].style.transform = `scaleX(${Math.max(...levels, 0)})`;
    return;
  }
  for (let i = 0; i < fills.length; i += 1) {
    fills[i].style.transform = `scaleY(${Math.max(MIN_BAR, levels[i] || 0)})`;
  }
}

/**
 * Show the live level strip and the elapsed timer in `host` while recording.
 * The strip replaces the host's other children (the record glyph) until
 * `stop()`, which puts them back. It does not stop the stream's tracks.
 *
 * Call it in the same tap that starts recording (see `createLevelSource`).
 *
 * @param {HTMLElement} host  the record button, or a container inside it.
 * @param {MediaStream} stream  the stream the recorder already has.
 * @param {object} [opts]
 * @param {number} [opts.bars=24]  bar count, 4 to 64.
 * @param {number} [opts.height=24]  strip height in px.
 * @param {boolean} [opts.reducedMotion]  one level meter instead of moving
 *        bars; defaults to the `prefers-reduced-motion` media query.
 * @param {boolean} [opts.timer=true]  show the elapsed m:ss.
 * @param {number} [opts.silenceMs=1500]  quiet this long reads as silent.
 * @param {number} [opts.floor=0.002]  RMS under which the input is quiet.
 * @param {object} [opts.source]  a `createLevelSource()` the caller owns, to
 *        share one AudioContext; it is not closed on stop.
 * @param {() => void} [opts.onSilent]  the input just went silent.
 * @param {() => void} [opts.onSignal]  sound was heard, the first time and
 *        again after a silent verdict.
 * @returns {() => void} stop(), safe to call more than once.
 */
export function attachRecWave(host, stream, opts) {
  const o = opts || {};
  const bars = clamp(Math.round(o.bars || DEFAULT_BARS), MIN_BARS, MAX_BARS);
  const reduced = typeof o.reducedMotion === 'boolean' ? o.reducedMotion : prefersReducedMotion();
  const silenceMs = o.silenceMs || SILENCE_MS;
  const floor = o.floor || SILENCE_RMS;
  const owned = !o.source;
  const source = o.source || createLevelSource(stream);
  if (source && stream) source.connect(stream);

  const { root, fills, timeEl } = buildWave(bars, reduced, o.height || DEFAULT_HEIGHT, o.timer !== false);

  host.dataset.recWave = 'on';
  host.appendChild(root);

  const startedAt = Date.now();
  let state = '';
  let heard = false;
  let quietSince = null;
  let lastTime = '';
  let stopped = false;

  function setState(next) {
    if (next === state) return;
    state = next;
    root.dataset.state = next;
    host.dataset.recWaveState = next;
  }

  const paint = (levels) => paintLevels(fills, reduced, levels);

  function tick() {
    const now = Date.now();
    if (timeEl) {
      const text = formatElapsed(now - startedAt);
      if (text !== lastTime) {
        timeEl.textContent = text;
        lastTime = text;
      }
    }
    const reading = source ? source.read(bars) : null;
    if (!reading) {
      // No Web Audio, or the context is not running yet: the timer alone, and
      // never a silent verdict about a level that was not measured.
      setState('unmeasured');
      paint([]);
      return;
    }
    if (quietSince === null) quietSince = now;
    if (reading.rms >= floor) {
      quietSince = now;
      const announce = !heard || state === 'silent';
      heard = true;
      setState('live');
      if (announce && o.onSignal) o.onSignal();
      paint(reading.levels);
      return;
    }
    if (state === 'silent') {
      paint([]);
      return;
    }
    if (now - quietSince >= silenceMs) {
      setState('silent');
      paint([]);
      if (o.onSilent) o.onSilent();
      return;
    }
    // Before the first verdict, or quiet for less than silenceMs: show what is there.
    setState('live');
    paint(reading.levels);
  }

  setState(source ? 'live' : 'unmeasured');
  tick();
  const timer = setInterval(tick, reduced ? REDUCED_TICK_MS : TICK_MS);

  return function stop() {
    if (stopped) return;
    stopped = true;
    clearInterval(timer);
    root.remove();
    delete host.dataset.recWave;
    delete host.dataset.recWaveState;
    if (owned && source) source.close();
  };
}
